(() => {
'use strict';
const source='https://openroad-flow-scripts.readthedocs.io/en/latest/tutorials/FlowTutorial.html';
const cases={
drc:{num:'01',title:'GCD：从短路标记找到重叠单元',label:'真实排查 / 官方教程有修复记录',file:'view_violation.webp',alt:'OpenROAD DRC Inspector 显示 met1 上 net51 与 net53 的 Short，底部日志显示 5 个 DRC 违规',anchor:'drc-viewer',intro:'右侧属性明确列出短路类型、金属层和涉事网络。先选中一个 marker，再看局部几何和来源对象。',points:[
[43,42,'违规位置','黄色斜线框是当前 marker。放大这里看接触关系；大面积红色本身不是“全部短路”。'],
[79,20,'错误类型与金属层','Inspector 显示 Short / met1，先确认是短路问题和所在层。'],
[79,27,'涉事网络','Sources 列出 net51 与 net53。应追踪两个不同网络为什么在这里接触。'],
[32,89,'本帧检查数量','截图日志写着 5 个 DRC 违规；官方教程另一运行记录为 7。不同帧不能拼成同一次测量。']
],after:`<div class="case-analysis"><div><h4>官方记录的根因与修复</h4><p>教程发现 output51 与 output53 放在同一坐标；调整 output53 的位置后重新布线，官方记录的剩余违规数为 0。</p></div><div><h4>验收时继续看什么？</h4><p>核对修复后的报告、版图和网表版本，再复查相关物理与电气影响。工具内路由违规归零，仍需项目规定的完整签核。</p></div></div><div class="case-diagram"><svg viewBox="0 0 720 205" role="img" aria-label="依据教程根因重绘：两个单元重叠，调整一个单元后不再重叠；并非实际版图坐标图"><text x="20" y="25" fill="#415c77" font-size="13">根因重绘 · 非按实际坐标比例</text><rect x="35" y="68" width="158" height="70" rx="5" fill="#f7dce2" stroke="#ba3a55"/><rect x="47" y="80" width="158" height="70" rx="5" fill="#dc8da3" fill-opacity=".65" stroke="#a82346" stroke-dasharray="5 3"/><text x="120" y="112" text-anchor="middle" fill="#81203b" font-size="14">output51 / 53</text><text x="120" y="180" text-anchor="middle" fill="#8b2d44" font-size="13">位置重叠</text><path d="M245 109H335l-12-7m12 7-12 7" fill="none" stroke="#48819f" stroke-width="2"/><rect x="380" y="68" width="138" height="75" rx="5" fill="#dceef5" stroke="#2b7c9e"/><rect x="550" y="68" width="138" height="75" rx="5" fill="#e4f3eb" stroke="#2f8a68"/><text x="449" y="111" text-anchor="middle" fill="#245d78" font-size="14">output51</text><text x="619" y="111" text-anchor="middle" fill="#216d51" font-size="14">output53</text><text x="533" y="180" text-anchor="middle" fill="#46667e" font-size="13">调整位置 → 重新布线 → 重新检查</text></svg></div>`},
timing:{num:'02',title:'Ibex：一条晚到 1.288 ns 的路径',label:'真实报告 / 原图有负裕量',file:'clock_path_update.webp',alt:'OpenROAD Ibex Timing Report 中 Setup 行显示 Required 12.000、Arrival 13.288、Slack -1.288，左侧高亮路径',anchor:'viewing-timing-report',intro:'这张图把版图高亮和路径报告放在一起。先读被选中行，再沿逐段延迟寻找值得检查的位置。',points:[
[42,47,'物理路径高亮','当前选中路径投射到版图上，方便观察空间分布。只凭颜色不能区分所有数据与时钟段。'],
[79,35,'Required、Arrival、Slack','选中行分别为 12.000、13.288、−1.288 ns：这个 setup 检查晚到 1.288 ns。'],
[94,35,'终点是输出端口','选中行的 End 为 instr_addr_o[31]。路径终点也可以是端口，要审核对应输出时序约束。'],
[80,78,'逐段详情','这里有引脚、累计时间、本段延迟、转换时间与负载。判断延迟主要来自单元、连线还是时钟，需要完整详情。']
],after:`<div class="timing-math"><span>Setup slack = required − arrival</span><b>12.000 − 13.288 = <em>−1.288 ns</em></b><small>由截图所选行直接计算；不是假定的修复结果。</small></div><div class="case-analysis"><div><h4>工程师怎样排查？</h4><p>先审核时钟和输出预算，再查看逐段延迟与物理位置。必要时评估单元驱动、负载、布局和绕线。</p></div><div><h4>改完怎样验证？</h4><p>更新寄生并复查所需场景的 setup、hold 等检查。原图未给出后续修复数据，这里不把建议当成成功结果。</p></div></div>`},
power:{num:'03',title:'GCD：电源网络与实际 IR 报告',label:'真实结构 / 官方静态分析输出',file:'gcd_pdn_gui.webp',alt:'OpenROAD GCD 电源网络规划，外围供电环与内部多层条带交错',anchor:'power-planning-and-analysis',intro:'图展示 GCD 供电网络；下方数值来自教程另一个静态 IR 测试步骤。两者用于理解流程，不宣称是同一运行版本。',points:[
[22,8,'外围粗金属结构','从外围向内部供电的结构。网络身份需要查对象属性，不能凭颜色猜测电源或地。'],
[48,36,'内部条带','供电需要从粗结构分配到局部。增加或加宽条带是否有帮助，要结合网络瓶颈重新分析。'],
[37,70,'局部接入','单元最终从局部电源轨获得供电。需要检查连通和各位置电压，而不只是观察整齐与否。'],
[77,84,'交叉不等于连接','俯视重叠需要结合金属层、网络和合法通孔判断。图本身不是压降热力图。']
],after:`<div class="ir-values"><div><span>官方输出 · 平均 IR drop</span><b>0.168 <small>mV</small></b></div><div><span>官方输出 · 最差 IR drop</span><b>0.298 <small>mV</small></b></div><div><span>官方输出 · 最低电压（舍入）</span><b>1.10 <small>V</small></b></div></div><p class="small">由教程输出 1.68e−04 V 和 2.98e−04 V 换算。最低电压仅保留原文有效位数；这些小设计结果不适合直接外推到其他芯片。</p><div class="case-analysis"><div><h4>还缺什么才能判合格？</h4><p>需要项目预算、分析角、供电边界和活动假设；实际芯片还可能要求动态分析。</p></div><div><h4>怎样继续定位？</h4><p>查看各位置电压和电流、浮空条带及供电源设置。静态分析与分段电流报告不能独立证明完整 EM 寿命签核通过。</p></div></div><p class="case-source">分析方法：<a href="https://openroad.readthedocs.io/en/latest/main/src/psm/README.html" target="_blank" rel="noopener">OpenROAD IR Drop Analysis ↗</a></p>`}
};
function figure(id){const d=cases[id];return `<figure class="real-figure" data-case="${id}"><div class="case-image ${id==='power'?'case-square':''}"><img src="assets/${d.file}" alt="${d.alt}" loading="lazy" width="${id==='power'?718:1682}" height="${id==='power'?583:id==='timing'?647:848}">${d.points.map((p,i)=>`<button class="case-pin ${i===0?'selected':''}" data-case-point="${i}" style="left:${p[0]}%;top:${p[1]}%" aria-pressed="${i===0}" aria-label="标记 ${i+1}：${p[2]}">${i+1}</button>`).join('')}</div><figcaption><span>OpenROAD 官方教程原图 · 编号为页面叠加</span><button class="btn" data-zoom="${id}">放大原图 ↗</button></figcaption><div class="case-point-list" role="group" aria-label="截图编号导读">${d.points.map((p,i)=>`<button data-case-point="${i}" class="${i===0?'selected':''}" aria-pressed="${i===0}"><b>${i+1}</b>${p[2]}</button>`).join('')}</div><div class="case-point-detail" aria-live="polite"><b>01 / ${d.points[0][2]}</b><p>${d.points[0][3]}</p></div></figure>`}
function block(id,compact=false){const d=cases[id];return `<section class="case-study ${compact?'case-embedded':''}" id="real-${id}"><div class="case-kicker">REAL CASE ${d.num} <span>${d.label}</span></div><h2 id="case-${id}-read">${d.title}</h2><p>${d.intro}</p>${figure(id)}${d.after}<p class="case-source">来源：<a href="${source}#${d.anchor}" target="_blank" rel="noopener">OpenROAD Flow Scripts Tutorial · ${id==='drc'?'DRC Viewer':id==='timing'?'Viewing Timing Report':'Power Planning And Analysis'} ↗</a></p></section>`}
function hub(){return `<article class="case-hub"><div class="crumb"><a href="#home">学习路径</a> / 真实案例与截图</div><span class="eyebrow">REAL DESIGNS · READ THE EVIDENCE</span><h1>从真实工具里，<br>看见一次检查怎么发生。</h1><p class="lead">3 个官方工程实例。点击截图编号逐项阅读，放大原图核对证据，再看定位与复查思路。</p><nav class="case-shortcuts" aria-label="案例快速导航"><a href="#cases/real-drc">01 · 短路排查</a><a href="#cases/real-timing">02 · 负时序裕量</a><a href="#cases/real-power">03 · 电源与压降</a></nav><div class="callout"><b>先读事实，再做判断</b>原图与原始数值来自公开官方教程；标注、算式和排查提示由本站编写。只有短路实例有官方修复记录。</div>${block('drc')}${block('timing')}${block('power')}<div class="callout"><b>下一步</b>把真实截图与<a href="#reports">简化报告导读</a>对照，再用<a href="#checklist">验收清单</a>核对证据是否齐全。</div></article>`}
window.SignoffCases={block,hub};
document.addEventListener('click',e=>{const pin=e.target.closest('[data-case-point]');if(pin){const f=pin.closest('[data-case]'),id=f.dataset.case,i=+pin.dataset.casePoint,p=cases[id].points[i];f.querySelectorAll('[data-case-point]').forEach(b=>{const yes=+b.dataset.casePoint===i;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes))});f.querySelector('.case-point-detail').innerHTML=`<b>${String(i+1).padStart(2,'0')} / ${p[2]}</b><p>${p[3]}</p>`;}const zoom=e.target.closest('[data-zoom]');if(zoom){const d=cases[zoom.dataset.zoom];let modal=document.querySelector('#case-zoom');if(!modal){modal=document.createElement('dialog');modal.id='case-zoom';modal.setAttribute('aria-labelledby','case-zoom-title');modal.innerHTML='<div class="dialog-head"><b id="case-zoom-title"></b><button data-close-zoom>关闭 Esc</button></div><div class="case-zoom-scroll"><img id="case-zoom-img" alt=""></div><p class="small">原始截图可横向滚动查看；手机上可用系统缩放。</p>';document.body.append(modal)}document.querySelector('#case-zoom-title').textContent=d.title;const img=document.querySelector('#case-zoom-img');img.src='assets/'+d.file;img.alt=d.alt;modal.showModal();}if(e.target.closest('[data-close-zoom]'))document.querySelector('#case-zoom').close()});
})();
